import * as store from "../runtime/store.js";
import type { Row } from "../runtime/store.js";
import type { Breed, Horse, Swipe } from "../types.js";

// The step may touch only the tables it declares.
const all = (table: "Horse" | "Swipe"): Row[] => store.all(table);
const find = (table: "Horse" | "Swipe", id: string): Row | undefined => store.find(table, id);

export async function pickCandidates(horse: Horse): Promise<Horse[]> {
  const swiped = new Set(
    (all("Swipe") as Swipe[])
      .filter((s) => s.horse_id === horse.id)
      .map((s) => s.target_id)
  );
  return (all("Horse") as Horse[]).filter(
    (h) => h.id !== horse.id && !swiped.has(h.id)
  );
}
